module top(input clk, input we, input [12:0] addr, input [0:0] d, output [0:0] q);
  cycloneiv_ram_block #(
    .operation_mode("single_port"),
    .ram_block_type("M9K"),
    .logical_ram_name("ram"),
    .port_a_logical_ram_depth(8192),
    .port_a_logical_ram_width(1),
    .port_a_first_address(0),
    .port_a_last_address(8191),
    .port_a_first_bit_number(0),
    .port_a_data_width(1),
    .port_a_address_width(13),
    .power_up_uninitialized("false"),
    .mem_init0(2048'),
    .mem_init1(2048'),
    .mem_init2(2048'),
    .mem_init3(2048'),
    .mem_init4(2048')
  ) ram (
    .clk0(clk), .portawe(we), .portaaddr(addr), .portadatain(d), .portadataout(q));
endmodule
